<script setup> import { ref, computed } from "vue"; import { useRouter } from "vue-router"; import { useAuthStore } from "@/stores/auth"; import { useThemeStore } from "@/stores/theme"; const router = useRouter(); const auth = useAuthStore(); const theme = useThemeStore(); const error = ref(""); const oldPassword = ref(""); const newPassword = ref(""); const confirmPassword = ref(""); const saving = ref(false); function apply() { error.value = ""; if (!oldPassword.value || !newPassword.value || !confirmPassword.value) { error.value = "Preencha todos os campos"; return; } if (newPassword.value !== confirmPassword.value) { error.value = "As senhas não conferem"; return; } saving.value = true; // TODO: chamar API /api/auth/password quando disponível setTimeout(() => { saving.value = false; router.push("/"); }, 1500); } function onKeyDown(e) { if (e.key === "Escape") router.push("/"); } </script> <template> <div class="min-h-screen flex items-center justify-center bg-gray-100 dark:bg-gray-800 p-4" > <div role="dialog" aria-modal="true" aria-labelledby="change-password-title" class="w-full max-w-md rounded-lg border p-6 shadow-lg dark:border-gray-700 dark:bg-gray-900" > <h2 id="change-password-title" class="mb-4 text-lg font-semibold text-black dark:text-white"> Alterar senha </h2> <label class="mb-1 block text-sm text-gray-700 dark:text-bodydark">Senha atual</label> <input v-model="oldPassword" type="password" placeholder="Digite sua senha atual" class="mt-1 block w-full rounded border border-stroke bg-white text-black px-3 py-2 focus:border-primary dark:border-form-strokedark dark:bg-form-input dark:text-white" /> <label class="mt-4 mb-1 block text-sm text-gray-700 dark:text-bodydark">Nova senha</label> <input v-model="newPassword" type="password" placeholder="Digite uma nova senha" class="mt-1 block w-full rounded border border-stroke bg-white text-black px-3 py-2 focus:border-primary dark:border-form-strokedark dark:bg-form-input dark:text-white" /> <label class="mt-4 mb-1 block text-sm text-gray-700 dark:text-bodydark">Confirmar nova senha</label> <input v-model="confirmPassword" type="password" placeholder="Confirme a nova senha" class="mt-1 block w-full rounded border border-stroke bg-white text-black px-3 py-2 focus:border-primary dark:border-form-strokedark dark:bg-form-input dark:text-white" /> <div v-if="error" class="mt-4 p-3 rounded bg-red-100 dark:bg-red-900 text-red-sm text-red"> {{ error }} </div> <button @click="apply" class="mt-6 w-full rounded-lg border border-primary px-4 py-2.5 text-sm font-medium text-white transition hover:bg-opacity-90 disabled:opacity-60" :disabled="saving" :class="{ 'opacity-60': saving }"> {{ saving ? "Salvando..." : "Alterar senha" </button> <button @click="$router.push('/')" class="mt-3 w-full rounded-lg border border-stroke px-4 py-2.5 text-sm font-medium text-body transition hover:border-primary dark:border-strokedark dark:text-bodydark" type="button"> Cancelar </button> </div> </template>